/**
 * Registry of types apps can narrow by declaration merging, e.g.
 *
 * ```ts
 * declare module 'homey' {
 *   interface HomeyTypes {
 *     app: MyApp
 *   }
 * }
 * ```
 *
 * This must be declared as part of the `homey` module itself (not a nested
 * module) so that the above consumer-side augmentation merges with it.
 */
declare module 'homey' {
    interface HomeyTypes {
    }
}
/**
 * The type of `Homey.app`: an app's own `HomeyTypes['app']` augmentation if declared, otherwise
 * the base `App` class.
 */
export type ResolvedApp = import('homey').HomeyTypes extends {
    app: infer TApp;
} ? TApp : import('../lib/App.js');
